def remaining_life(previous_mm: float, current_mm: float, years_between: float, min_required_mm: float) -> dict:
    if years_between <= 0:
        raise ValueError("years_between must be positive")

    corrosion_rate_mm_yr = round((previous_mm - current_mm) / years_between, 3)

    if corrosion_rate_mm_yr <= 0:
        remaining_life_yr = None
    else:
        if current_mm <= min_required_mm:
            remaining_life_yr = 0.0
